def tokenize_ninja_line(text):
    tokens = []
    i = 0
    n = len(text)
    curr = []

    while i < n:
        c = text[i]
        if c == '$':
            if i + 1 < n:
                nc = text[i+1]
                if nc == '$':
                    curr.append('$')
                    i += 2
                    continue
                elif nc == ' ':
                    curr.append(' ')
                    i += 2
                    continue
                elif nc == ':':
                    curr.append(':')
                    i += 2
                    continue
                elif nc == '\n':
                    i += 2
                    continue
                curr.append('$')
                i += 1
            else:
                i += 1
        elif c in ' \t\n\r':
            if curr:
                tokens.append(''.join(curr))
                curr = []
            i += 1
        elif c == ':' or c == '=':
            if curr:
                tokens.append(''.join(curr))
                curr = []
            tokens.append(c)
            i += 1
        elif c == '|':
            if curr:
                tokens.append(''.join(curr))
                curr = []
            if i + 1 < n and text[i+1] == '|':
                tokens.append('||')
                i += 2
            elif i + 1 < n and text[i+1] == '@':
                tokens.append('|@')
                i += 2
            else:
                tokens.append('|')
                i += 1
        else:
            curr.append(c)
            i += 1

    if curr:
        tokens.append(''.join(curr))
    return tokens

