def expand_vars(val: str, env: dict) -> str:
    i = 0
    n = len(val)
    res = []
    while i < n:
        c = val[i]
        if c == '$':
            if i + 1 < n:
                nc = val[i+1]
                if nc == '$':
                    res.append('$')
                    i += 2
                elif nc == ' ':
                    res.append(' ')
                    i += 2
                elif nc == ':':
                    res.append(':')
                    i += 2
                elif nc == '\n':
                    i += 2
                elif nc == '{':
                    end = val.find('}', i + 2)
                    if end != -1:
                        var_name = val[i+2:end]
                        res.append(env.get(var_name, ''))
                        i = end + 1
                    else:
                        res.append(val[i:])
                        break
                elif nc.isalnum() or nc in '_-':
                    j = i + 1
                    while j < n and (val[j].isalnum() or val[j] in '_-'):
                        j += 1
                    var_name = val[i+1:j]
                    res.append(env.get(var_name, ''))
                    i = j
                else:
                    res.append(nc)
                    i += 2
            else:
                i += 1
        else:
            res.append(c)
            i += 1
    return ''.join(res)

