#!/usr/bin/env python3
import os
import sys
import time
import json
import shlex
import hashlib
import subprocess
import getopt
import re
from concurrent.futures import ThreadPoolExecutor, as_completed

VERSION = "1.14.0.git"

def get_cpu_count():
    cpus = 0
    try:
        if os.path.exists('/sys/fs/cgroup/cpu.max'):
            with open('/sys/fs/cgroup/cpu.max', 'r') as f:
                quota, period = f.read().split()
                if quota != 'max':
                    cpus = int(int(quota) / int(period))
    except Exception:
        pass
    if cpus <= 0:
        try:
            if os.path.exists('/sys/fs/cgroup/cpu/cpu.cfs_quota_us'):
                with open('/sys/fs/cgroup/cpu/cpu.cfs_quota_us', 'r') as f1, open('/sys/fs/cgroup/cpu/cpu.cfs_period_us', 'r') as f2:
                    q = int(f1.read().strip())
                    p = int(f2.read().strip())
                    if q > 0 and p > 0:
                        cpus = int(q / p)
        except Exception:
            pass
    if cpus <= 0:
        try:
            cpus = len(os.sched_getaffinity(0))
        except Exception:
            cpus = os.cpu_count() or 1
    return cpus

def get_default_j():
    cpus = get_cpu_count()
    if cpus <= 2:
        return cpus + 1
    return cpus + 2

def compute_cmd_hash(cmd: str) -> str:
    val = int(hashlib.md5(cmd.encode('utf-8')).hexdigest()[:16], 16)
    return f"{val:x}"

def expand_vars(val: str, env: dict) -> str:
    i = 0
    n = len(val)
    res = []
    while i < n:
        c = val[i]
        if c == '$':
            if i + 1 < n:
                nc = val[i+1]
                if nc == '$':
                    res.append('$')
                    i += 2
                elif nc == ' ':
                    res.append(' ')
                    i += 2
                elif nc == ':':
                    res.append(':')
                    i += 2
                elif nc == '\n':
                    i += 2
                elif nc == '{':
                    end = val.find('}', i + 2)
                    if end != -1:
                        var_name = val[i+2:end]
                        res.append(env.get(var_name, ''))
                        i = end + 1
                    else:
                        res.append(val[i:])
                        break
                elif nc.isalnum() or nc in '_-':
                    j = i + 1
                    while j < n and (val[j].isalnum() or val[j] in '_-'):
                        j += 1
                    var_name = val[i+1:j]
                    res.append(env.get(var_name, ''))
                    i = j
                else:
                    res.append(nc)
                    i += 2
            else:
                i += 1
        else:
            res.append(c)
            i += 1
    return ''.join(res)

class Rule:
    def __init__(self, name, bindings):
        self.name = name
        self.bindings = bindings

class Edge:
    def __init__(self, rule, outputs, implicit_outputs, inputs, implicit_inputs, order_only_inputs, validations, bindings, scope_env):
        self.rule = rule
        self.outputs = outputs
        self.implicit_outputs = implicit_outputs
        self.inputs = inputs
        self.implicit_inputs = implicit_inputs
        self.order_only_inputs = order_only_inputs
        self.validations = validations
        self.bindings = bindings
        self.scope_env = scope_env
        self.pool = None
        self.dyndep = None
        self.is_dirty = False
        self.id = id(self)

    def evaluate_var(self, var_name, shell_escape=False):
        if var_name == 'in':
            paths = self.inputs
            if shell_escape:
                return ' '.join(shlex.quote(p) for p in paths)
            return ' '.join(paths)
        elif var_name == 'out':
            paths = self.outputs
            if shell_escape:
                return ' '.join(shlex.quote(p) for p in paths)
            return ' '.join(paths)
        elif var_name == 'in_newline':
            paths = self.inputs
            if shell_escape:
                return '\n'.join(shlex.quote(p) for p in paths)
            return '\n'.join(paths)

        if var_name in self.bindings:
            return self.bindings[var_name]

        if isinstance(self.rule, Rule) and var_name in self.rule.bindings:
            raw_val = self.rule.bindings[var_name]
            # expand raw_val in context
            return self.expand_in_edge(raw_val, shell_escape=shell_escape)

        if var_name in self.scope_env:
            return self.scope_env[var_name]

        return ''

    def expand_in_edge(self, raw_val: str, shell_escape=False) -> str:
        i = 0
        n = len(raw_val)
        res = []
        while i < n:
            c = raw_val[i]
            if c == '$':
                if i + 1 < n:
                    nc = raw_val[i+1]
                    if nc == '$':
                        res.append('$')
                        i += 2
                    elif nc == ' ':
                        res.append(' ')
                        i += 2
                    elif nc == ':':
                        res.append(':')
                        i += 2
                    elif nc == '\n':
                        i += 2
                    elif nc == '{':
                        end = raw_val.find('}', i + 2)
                        if end != -1:
                            var_name = raw_val[i+2:end]
                            res.append(self.evaluate_var(var_name, shell_escape=shell_escape))
                            i = end + 1
                        else:
                            res.append(raw_val[i:])
                            break
                    elif nc.isalnum() or nc in '_-':
                        j = i + 1
                        while j < n and (raw_val[j].isalnum() or raw_val[j] in '_-'):
                            j += 1
                        var_name = raw_val[i+1:j]
                        res.append(self.evaluate_var(var_name, shell_escape=shell_escape))
                        i = j
                    else:
                        res.append(nc)
                        i += 2
                else:
                    i += 1
            else:
                res.append(c)
                i += 1
        return ''.join(res)

    def get_command(self):
        if self.rule == 'phony':
            return ''
        if isinstance(self.rule, Rule) and 'command' in self.rule.bindings:
            return self.expand_in_edge(self.rule.bindings['command'], shell_escape=True)
        return self.bindings.get('command', '')

    def get_description(self):
        if isinstance(self.rule, Rule) and 'description' in self.rule.bindings:
            return self.expand_in_edge(self.rule.bindings['description'], shell_escape=False)
        return self.bindings.get('description', '')

    def get_depfile(self):
        if isinstance(self.rule, Rule) and 'depfile' in self.rule.bindings:
            return self.expand_in_edge(self.rule.bindings['depfile'], shell_escape=False)
