                idx += 1

            elif line.startswith('include '):
                inc_path = expand_vars(line[8:].strip(), env)
                try:
                    self.parse_file(inc_path, env=env, parent_rules=rules)
                except FileNotFoundError:
                    sys.stderr.write(f"ninja: error: {fpath}:{lineno}: loading '{inc_path}': No such file or directory\n{line}\n{' ' * (len(line)-1)}^ near here\n")
                    sys.exit(1)
                idx += 1

            elif line.startswith('subninja '):
                sub_path = expand_vars(line[9:].strip(), env)
                sub_env = dict(env)
                try:
                    self.parse_file(sub_path, env=sub_env, parent_rules=rules)
                except FileNotFoundError:
                    sys.stderr.write(f"ninja: error: {fpath}:{lineno}: loading '{sub_path}': No such file or directory\n{line}\n{' ' * (len(line)-1)}^ near here\n")
                    sys.exit(1)
                idx += 1

            elif line.startswith('pool '):
                pool_name = line[5:].strip()
                depth = 1
                idx += 1
                while idx < num_lines and logical_lines[idx][0] > 0:
                    _, b_line, _, _ = logical_lines[idx]
                    if '=' in b_line:
                        k, v = b_line.split('=', 1)
                        if k.strip() == 'depth':
                            depth = int(expand_vars(v.strip(), env))
                    idx += 1
                self.pools[pool_name] = depth

            elif '=' in line:
                k, v = line.split('=', 1)
                k = k.strip()
                v = v.strip()
                env[k] = expand_vars(v, env)
                if k == 'builddir':
                    self.builddir = env[k]
                elif k == 'ninja_required_version':
                    self.ninja_required_version = env[k]
                idx += 1

            else:
                sys.stderr.write(f"ninja: error: {fpath}:{lineno}: expected '=', got newline\n{line}\n{' ' * (len(line)-1)}^ near here\n")
                sys.exit(1)

