class SubtoolHandler:
    def __init__(self, parser, log, deps, args, cwd):
        self.parser = parser
        self.log = log
        self.deps = deps
        self.args = args
        self.cwd = cwd

    def run(self, tool_name):
        if tool_name == 'list':
            print("ninja subtools:")
            print("     browse  browse dependency graph in a web browser")
            print("      clean  clean built files")
            print("   commands  list all commands required to rebuild given targets")
            print("     inputs  list all inputs required to rebuild given targets")
            print("multi-inputs  print one or more sets of inputs required to build targets")
            print("       deps  show dependencies stored in the deps log")
            print("missingdeps  check deps log dependencies on generated files")
            print("      graph  output graphviz dot file for targets")
            print("      query  show inputs/outputs for a path")
            print("    targets  list targets by their rule or depth in the DAG")
            print("     compdb  dump JSON compilation database to stdout")
            print("compdb-targets  dump JSON compilation database for a given list of targets to stdout")
            print("  recompact  recompacts ninja-internal data structures")
            print("      restat  restats all outputs in the build log")
            print("      rules  list all rules")
            print("  cleandead  clean built files that are no longer produced by the manifest")
            return 0

        elif tool_name == 'browse':
            print("ninja: python is required for the browse tool")
            return 1

        elif tool_name == 'rules':
            show_desc = False
            if '-d' in self.args:
                show_desc = True
            for rname, rule in self.parser.rules.items():
                if show_desc and 'description' in rule.bindings:
                    print(f"{rname}: {rule.bindings['description']}")
                else:
                    print(rname)
            return 0

        elif tool_name == 'clean':
            clean_gen = False
            clean_rules = False
            targets = []
            i = 0
            while i < len(self.args):
                arg = self.args[i]
                if arg == '-g':
                    clean_gen = True
                elif arg == '-r':
                    clean_rules = True
                elif not arg.startswith('-'):
                    targets.append(arg)
                i += 1

            files_to_clean = set()
            if clean_rules and targets:
                rule_set = set(targets)
                for edge in self.parser.edges:
                    rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                    if rname in rule_set:
                        for out in edge.outputs + edge.implicit_outputs:
                            files_to_clean.add(out)
            elif targets:
                for t in targets:
                    node = self.parser.nodes.get(t)
                    if node and node.in_edge:
                        for out in node.in_edge.outputs + node.in_edge.implicit_outputs:
                            files_to_clean.add(out)
            else:
                for edge in self.parser.edges:
                    if not clean_gen and edge.get_generator():
                        continue
                    for out in edge.outputs + edge.implicit_outputs:
                        files_to_clean.add(out)

            removed_count = 0
            for f in files_to_clean:
                if os.path.exists(f):
                    try:
                        os.remove(f)
                        removed_count += 1
                    except Exception:
                        pass

            print(f"Cleaning... {removed_count} files.")
            return 0

        elif tool_name == 'commands':
            single_target_only = '-s' in self.args
            targets = [a for a in self.args if not a.startswith('-')]
            edges = self.get_edges_for_targets(targets)
            if single_target_only and edges:
                edges = [edges[-1]]
            for edge in edges:
                cmd = edge.get_command()
                if cmd:
                    print(cmd)
            return 0

        elif tool_name == 'inputs':
            print0 = '-0' in self.args or '--print0' in self.args
            no_escape = '-E' in self.args or '--no-shell-escape' in self.args
            dep_order = '-d' in self.args or '--dependency-order' in self.args
            targets = [a for a in self.args if not a.startswith('-')]
            edges = self.get_edges_for_targets(targets)
            inputs = []
            seen = set()
            for edge in edges:
                for inp in edge.inputs + edge.implicit_inputs:
                    if inp not in seen:
                        seen.add(inp)
                        inputs.append(inp)
            if not dep_order:
                inputs.sort()

            formatted = []
            for inp in inputs:
                formatted.append(inp if no_escape else shlex.quote(inp))

            sep = '\0' if print0 else '\n'
            out_str = sep.join(formatted)
            if print0:
                sys.stdout.write(out_str)
            else:
                if out_str:
                    print(out_str)
            return 0

        elif tool_name == 'multi-inputs':
            delim = '\t'
            print0 = False
            targets = []
            i = 0
            while i < len(self.args):
                arg = self.args[i]
                if arg.startswith('--delimiter='):
                    delim = arg.split('=', 1)[1]
                elif arg == '-d' and i + 1 < len(self.args):
                    delim = self.args[i+1]
                    i += 1
                elif arg == '-0' or arg == '--print0':
                    print0 = True
                elif not arg.startswith('-'):
                    targets.append(arg)
                i += 1

            edges = self.get_edges_for_targets(targets)
            terminator = '\0' if print0 else '\n'
            for edge in edges:
                target_name = edge.outputs[0] if edge.outputs else ''
                for inp in edge.inputs + edge.implicit_inputs:
                    sys.stdout.write(f"{target_name}{delim}{inp}{terminator}")
            return 0

        elif tool_name == 'query':
            targets = [a for a in self.args if not a.startswith('-')]
            if not targets:
                sys.stderr.write("ninja: error: expected a target to query\n")
                return 1

            for t in targets:
                node = self.parser.nodes.get(t)
                if not node and not any(e for e in self.parser.edges if t in e.outputs or t in e.inputs):
                    sys.stderr.write(f"ninja: fatal: unknown target '{t}'\n")
                    return 1

                print(f"{t}:")
                if node and node.in_edge:
                    edge = node.in_edge
                    rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                    print(f"  input: {rname}")
                    for inp in edge.inputs:
                        print(f"    {inp}")
                    if edge.implicit_inputs:
                        for inp in edge.implicit_inputs:
                            print(f"    | {inp}")
                    if edge.order_only_inputs:
                        for inp in edge.order_only_inputs:
                            print(f"    || {inp}")

                    if edge.validations:
                        print("  validations:")
                        for val in edge.validations:
                            print(f"    {val}")

                # find outputs where t is input
                outs = []
                if node:
                    for e in node.out_edges:
                        outs.extend(e.outputs)
                if node and node.in_edge:
                    print("  outputs:")
                    for out in outs:
                        print(f"    {out}")
                elif outs:
                    print("  outputs:")
                    for out in outs:
                        print(f"    {out}")
            return 0

        elif tool_name == 'targets':
            mode = 'depth'
            mode_arg = 1
            if self.args:
                m = self.args[0]
                if m == 'all':
                    for edge in self.parser.edges:
                        rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                        for out in edge.outputs:
                            print(f"{out}: {rname}")
                    return 0
                elif m == 'rule':
                    if len(self.args) < 2:
                        sys.stderr.write("ninja: error: expected rule name\n")
                        return 1
                    r_target = self.args[1]
                    for edge in self.parser.edges:
                        rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                        if rname == r_target:
                            for out in edge.outputs:
                                print(out)
                    return 0
                elif m == 'depth':
