def compute_cmd_hash(cmd: str) -> str:
    val = int(hashlib.md5(cmd.encode('utf-8')).hexdigest()[:16], 16)
    return f"{val:x}"

def expand_vars(val: str, env: dict) -> str:
    i = 0
    n = len(val)
    res = []
    while i < n:
        c = val[i]
        if c == '$':
            if i + 1 < n:
                nc = val[i+1]
                if nc == '$':
