                elif nc == ':':
                    res.append(':')
                    i += 2
                elif nc == '\n':
                    i += 2
                elif nc == '{':
                    end = val.find('}', i + 2)
                    if end != -1:
                        var_name = val[i+2:end]
                        res.append(env.get(var_name, ''))
                        i = end + 1
                    else:
                        res.append(val[i:])
                        break
                elif nc.isalnum() or nc in '_-':
                    j = i + 1
                    while j < n and (val[j].isalnum() or val[j] in '_-'):
                        j += 1
                    var_name = val[i+1:j]
                    res.append(env.get(var_name, ''))
                    i = j
                else:
