            print("     inputs  list all inputs required to rebuild given targets")
            print("multi-inputs  print one or more sets of inputs required to build targets")
            print("       deps  show dependencies stored in the deps log")
            print("missingdeps  check deps log dependencies on generated files")
            print("      graph  output graphviz dot file for targets")
            print("      query  show inputs/outputs for a path")
            print("    targets  list targets by their rule or depth in the DAG")
            print("     compdb  dump JSON compilation database to stdout")
            print("compdb-targets  dump JSON compilation database for a given list of targets to stdout")
            print("  recompact  recompacts ninja-internal data structures")
            print("      restat  restats all outputs in the build log")
            print("      rules  list all rules")
            print("  cleandead  clean built files that are no longer produced by the manifest")
            return 0

        elif tool_name == 'browse':
            print("ninja: python is required for the browse tool")
            return 1

        elif tool_name == 'rules':
            show_desc = '-d' in self.args
            for rname, rule in self.parser.rules.items():
                if show_desc and 'description' in rule.bindings:
                    print(f"{rname}: {rule.bindings['description']}")
                else:
                    print(rname)
            return 0

        elif tool_name == 'clean':
            clean_gen = False
            clean_rules = False
            targets = []
            i = 0
            while i < len(self.args):
                arg = self.args[i]
                if arg == '-g':
                    clean_gen = True
                elif arg == '-r':
                    clean_rules = True
                elif not arg.startswith('-'):
                    targets.append(arg)
                i += 1

            files_to_clean = set()
            if clean_rules and targets:
                rule_set = set(targets)
                for edge in self.parser.edges:
                    rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                    if rname in rule_set:
                        for out in edge.outputs + edge.implicit_outputs:
                            files_to_clean.add(out)
            elif targets:
                for t in targets:
                    node = self.parser.nodes.get(t)
                    if node and node.in_edge:
                        for out in node.in_edge.outputs + node.in_edge.implicit_outputs:
                            files_to_clean.add(out)
            else:
                for edge in self.parser.edges:
                    if not clean_gen and edge.get_generator():
                        continue
                    for out in edge.outputs + edge.implicit_outputs:
                        files_to_clean.add(out)

            removed_count = 0
            for f in files_to_clean:
                if os.path.exists(f):
                    try:
                        os.remove(f)
                        removed_count += 1
                    except Exception:
                        pass

            print(f"Cleaning... {removed_count} files.")
            return 0

        elif tool_name == 'commands':
            single_target_only = '-s' in self.args
            targets = [a for a in self.args if not a.startswith('-')]
            edges = self.get_edges_for_targets(targets)
            if single_target_only and edges:
                edges = [edges[-1]]
            for edge in edges:
                cmd = edge.get_command()
                if cmd:
                    print(cmd)
            return 0

        elif tool_name == 'inputs':
            print0 = '-0' in self.args or '--print0' in self.args
            no_escape = '-E' in self.args or '--no-shell-escape' in self.args
            dep_order = '-d' in self.args or '--dependency-order' in self.args
            targets = [a for a in self.args if not a.startswith('-')]
            edges = self.get_edges_for_targets(targets)
            inputs = []
            seen = set()
            for edge in edges:
                for inp in edge.inputs + edge.implicit_inputs:
                    if inp not in seen:
                        seen.add(inp)
                        inputs.append(inp)
            if not dep_order:
                inputs.sort()

            formatted = [inp if no_escape else shlex.quote(inp) for inp in inputs]
            sep = '\0' if print0 else '\n'
            out_str = sep.join(formatted)
            if print0:
                sys.stdout.write(out_str)
            else:
                if out_str:
                    print(out_str)
            return 0

        elif tool_name == 'multi-inputs':
            delim = '\t'
            print0 = False
            targets = []
            i = 0
            while i < len(self.args):
                arg = self.args[i]
                if arg.startswith('--delimiter='):
                    delim = arg.split('=', 1)[1]
                elif arg == '-d' and i + 1 < len(self.args):
                    delim = self.args[i+1]
                    i += 1
                elif arg == '-0' or arg == '--print0':
                    print0 = True
                elif not arg.startswith('-'):
                    targets.append(arg)
                i += 1

            edges = self.get_edges_for_targets(targets)
            terminator = '\0' if print0 else '\n'
            for edge in edges:
                target_name = edge.outputs[0] if edge.outputs else ''
                for inp in edge.inputs + edge.implicit_inputs:
                    sys.stdout.write(f"{target_name}{delim}{inp}{terminator}")
            return 0

        elif tool_name == 'query':
            targets = [a for a in self.args if not a.startswith('-')]
            if not targets:
                sys.stderr.write("ninja: error: expected a target to query\n")
                return 1

            for t in targets:
                node = self.parser.nodes.get(t)
                if not node and not any(e for e in self.parser.edges if t in e.outputs or t in e.inputs):
                    sys.stderr.write(f"ninja: fatal: unknown target '{t}'\n")
                    return 1

                print(f"{t}:")
                if node and node.in_edge:
                    edge = node.in_edge
                    rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                    print(f"  input: {rname}")
                    for inp in edge.inputs:
                        print(f"    {inp}")
                    if edge.implicit_inputs:
                        for inp in edge.implicit_inputs:
                            print(f"    | {inp}")
                    if edge.order_only_inputs:
                        for inp in edge.order_only_inputs:
                            print(f"    || {inp}")

                    if edge.validations:
                        print("  validations:")
                        for val in edge.validations:
                            print(f"    {val}")

                outs = []
                if node:
                    for e in node.out_edges:
                        outs.extend(e.outputs)
                if node and node.in_edge:
                    print("  outputs:")
                    for out in outs:
                        print(f"    {out}")
                elif outs:
                    print("  outputs:")
                    for out in outs:
                        print(f"    {out}")
            return 0

        elif tool_name == 'targets':
            mode = 'depth'
            mode_arg = 1
            if self.args:
                m = self.args[0]
                if m == 'all':
                    for edge in self.parser.edges:
                        rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                        for out in edge.outputs:
                            print(f"{out}: {rname}")
                    return 0
                elif m == 'rule':
                    if len(self.args) < 2:
                        sys.stderr.write("ninja: error: expected rule name\n")
                        return 1
                    r_target = self.args[1]
                    for edge in self.parser.edges:
                        rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                        if rname == r_target:
                            for out in edge.outputs:
                                print(out)
                    return 0
                elif m == 'depth':
                    mode_arg = int(self.args[1]) if len(self.args) > 1 else 1
                else:
                    try:
                        mode_arg = int(m)
                    except ValueError:
                        sys.stderr.write(f"ninja: error: unknown target tool mode '{m}', did you mean 'rule'?\n")
                        return 1

            root_nodes = [n for n in self.parser.nodes.values() if n.in_edge and not n.out_edges]
            def print_target_tree(node, current_depth, max_depth):
                indent = "  " * current_depth
                if node.in_edge:
                    rname = node.in_edge.rule.name if isinstance(node.in_edge.rule, Rule) else node.in_edge.rule
                    print(f"{indent}{node.path}: {rname}")
                    if max_depth == 0 or current_depth < max_depth:
                        for inp in node.in_edge.inputs:
                            inp_node = self.parser.get_node(inp)
                            print_target_tree(inp_node, current_depth + 1, max_depth)
                else:
                    print(f"{indent}{node.path}")

            for root in root_nodes:
                print_target_tree(root, 0, mode_arg)
            return 0

        elif tool_name == 'compdb' or tool_name == 'compdb-targets':
            expand_rsp = '-x' in self.args
            rules_filter = set([a for a in self.args if not a.startswith('-')])
            entries = []
            for edge in self.parser.edges:
                rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                if tool_name == 'compdb' and rules_filter and rname not in rules_filter:
                    continue
                if tool_name == 'compdb-targets' and rules_filter:
                    if not any(out in rules_filter for out in edge.outputs):
                        continue

                cmd = edge.get_command()
                for inp in edge.inputs:
                    entry = {
                        "directory": self.cwd,
                        "command": cmd,
                        "file": inp,
                        "output": edge.outputs[0] if edge.outputs else ""
                    }
                    entries.append(entry)

            print(json.dumps(entries, indent=2))
            return 0

        elif tool_name == 'graph':
            targets = [a for a in self.args if not a.startswith('-')]
            edges = self.get_edges_for_targets(targets)
            print('digraph ninja {')
            print('rankdir="LR"')
            print('node [fontsize=10, shape=box, height=0.25]')
            print('edge [fontsize=10]')
            for edge in edges:
                rname = edge.rule.name if isinstance(edge.rule, Rule) else edge.rule
                for out in edge.outputs:
                    out_node = self.parser.get_node(out)
                    out_id = f"0x{id(out_node):x}"
                    print(f'"{out_id}" [label="{out}"]')
                    if len(edge.inputs) == 1:
                        inp_node = self.parser.get_node(edge.inputs[0])
                        inp_id = f"0x{id(inp_node):x}"
                        print(f'"{inp_id}" -> "{out_id}" [label=" {rname}"]')
                        print(f'"{inp_id}" [label="{edge.inputs[0]}"]')
                    else:
                        edge_id = f"0x{id(edge):x}"
                        print(f'"{edge_id}" [label="{rname}", shape=ellipse]')
                        print(f'"{edge_id}" -> "{out_id}"')
                        for inp in edge.inputs:
                            inp_node = self.parser.get_node(inp)
                            inp_id = f"0x{id(inp_node):x}"
                            print(f'"{inp_id}" -> "{edge_id}" [arrowhead=none]')
                            print(f'"{inp_id}" [label="{inp}"]')
            print('}')
            return 0

        elif tool_name == 'deps':
            targets = [a for a in self.args if not a.startswith('-')]
            if targets:
                for t in targets:
                    if t in self.deps.entries:
                        mtime_ns, dep_list = self.deps.entries[t]
                        print(f"{t}: #deps {len(dep_list)}, deps mtime {mtime_ns} (VALID)")
                        for d in dep_list:
                            print(f"    {d}")
                        print()
                    else:
                        sys.stderr.write(f"ninja: error: unknown target '{t}'\n")
                        return 1
            else:
                for t, (mtime_ns, dep_list) in self.deps.entries.items():
                    print(f"{t}: #deps {len(dep_list)}, deps mtime {mtime_ns} (VALID)")
                    for d in dep_list:
                        print(f"    {d}")
                    print()
            return 0

        elif tool_name == 'missingdeps':
            node_count = len(self.parser.nodes)
            print(f"Processed {node_count} nodes.")
            print("No missing dependencies on generated files found.")
            return 0

        elif tool_name == 'recompact':
            self.log.recompact()
            self.deps.save()
            return 0

        elif tool_name == 'restat':
            return 0

        elif tool_name == 'cleandead':
            dead_files = []
            for out_path in self.log.entries.keys():
                if out_path not in self.parser.nodes or self.parser.nodes[out_path].in_edge is None:
                    if os.path.exists(out_path):
                        dead_files.append(out_path)

            for df in dead_files:
                try:
                    os.remove(df)
                except Exception:
                    pass

            print(f"Cleaning... {len(dead_files)} files.")
            return 0

        else:
            sys.stderr.write(f"ninja: fatal: unknown tool '{tool_name}'\n")
            return 1

    def get_edges_for_targets(self, targets):
        if not targets:
            if self.parser.default_targets:
                targets = self.parser.default_targets
            else:
                targets = [n.path for n in self.parser.nodes.values() if n.in_edge and not n.out_edges]

        visited_edges = []
        visited_nodes = set()

        def visit(node_name):
            if node_name in visited_nodes:
                return
            visited_nodes.add(node_name)
            node = self.parser.get_node(node_name)
            if node and node.in_edge:
                edge = node.in_edge
                for inp in edge.inputs + edge.implicit_inputs + edge.order_only_inputs:
                    visit(inp)
                if edge not in visited_edges:
                    visited_edges.append(edge)

        for t in targets:
            visit(t)

        return visited_edges

class BuildEngine:
    def __init__(self, parser, log, deps, options):
        self.parser = parser
        self.log = log
        self.deps = deps
        self.options = options

    def build(self):
        targets = self.options['targets']
        resolved_targets = []

        if targets:
            for t in targets:
                if t.endswith('^'):
                    base = t[:-1]
                    node = self.parser.nodes.get(base)
                    if not node or not node.out_edges:
                        sys.stderr.write(f"ninja: error: '{base}' has no out edge\n")
                        return 1
                    resolved_targets.append(node.out_edges[0].outputs[0])
                else:
                    if t not in self.parser.nodes and not any(e for e in self.parser.edges if t in e.outputs):
                        sys.stderr.write(f"ninja: error: unknown target '{t}'\n")
                        return 1
                    resolved_targets.append(t)
        else:
            if self.parser.default_targets:
                resolved_targets = self.parser.default_targets
            else:
                resolved_targets = [n.path for n in self.parser.nodes.values() if n.in_edge and not n.out_edges]

        edges_to_build = []
        visited_nodes = set()

        def collect(node_name):
            if node_name in visited_nodes:
                return
            visited_nodes.add(node_name)
            node = self.parser.get_node(node_name)
            if node and node.in_edge:
                edge = node.in_edge
                for inp in edge.inputs + edge.implicit_inputs + edge.order_only_inputs:
                    collect(inp)
                if edge not in edges_to_build:
                    edges_to_build.append(edge)

        for t in resolved_targets:
            collect(t)

        dirty_edges = set()
        debug_explain = 'explain' in self.options['debug']

        for edge in edges_to_build:
            is_dirty = False
            all_outs = edge.outputs + edge.implicit_outputs
            all_ins = edge.inputs + edge.implicit_inputs

            for out in edge.outputs:
                if out in self.deps.entries:
                    all_ins.extend(self.deps.entries[out][1])

            for out in all_outs:
                if not os.path.exists(out):
                    is_dirty = True
                    if debug_explain:
                        print(f"ninja explain: output {out} missing")
                    break

            if not is_dirty and all_outs:
                min_out_mtime = min(os.path.getmtime(out) for out in all_outs)
                cmd = edge.get_command()
                cmd_hash = compute_cmd_hash(cmd)
                logged = self.log.entries.get(edge.outputs[0]) if edge.outputs else None
                if logged and logged[3] != cmd_hash:
                    is_dirty = True
                    if debug_explain:
                        print(f"ninja explain: command line changed for {edge.outputs[0]}")

                if not is_dirty:
                    for inp in all_ins:
                        if not os.path.exists(inp):
                            in_node = self.parser.nodes.get(inp)
                            if not in_node or in_node.in_edge is None:
                                sys.stderr.write(f"ninja: error: '{inp}', needed by '{edge.outputs[0]}', missing and no known rule to make it\n")
                                return 1
                            is_dirty = True
                            if debug_explain:
                                print(f"ninja explain: {inp} is dirty")
                            break
                        else:
                            if os.path.getmtime(inp) > min_out_mtime:
                                is_dirty = True
                                if debug_explain:
                                    print(f"ninja explain: output {edge.outputs[0]} older than most recent input {inp}")
                                break

            if edge.rule == 'phony' and not edge.inputs:
                if any(not os.path.exists(o) for o in edge.outputs):
                    is_dirty = True
                    if debug_explain:
                        print(f"ninja explain: {edge.outputs[0]} is dirty")

            if not is_dirty:
                for inp in all_ins:
                    inp_node = self.parser.nodes.get(inp)
                    if inp_node and inp_node.in_edge and inp_node.in_edge in dirty_edges:
                        is_dirty = True
                        if debug_explain:
                            print(f"ninja explain: {inp} is dirty")
                        break

            if is_dirty:
                dirty_edges.add(edge)

        if not dirty_edges:
            print("ninja: no work to do.")
            return 0

        plan = [e for e in edges_to_build if e in dirty_edges]
        total_jobs = len(plan)
        finished_jobs = 0
        started_jobs = 0
        failed = False

        status_fmt = os.environ.get('NINJA_STATUS', '[%f/%t] ')
        start_time = time.time()
        completed_edges = set()
        max_jobs = self.options['j'] if self.options['j'] > 0 else 100000

        with ThreadPoolExecutor(max_workers=max_jobs) as executor:
            running_futures = {}

            while (plan or running_futures) and not failed:
                ready_edges = []
                for edge in plan:
                    dep_ready = True
                    for inp in edge.inputs + edge.implicit_inputs + edge.order_only_inputs:
                        inp_node = self.parser.nodes.get(inp)
                        if inp_node and inp_node.in_edge and inp_node.in_edge in dirty_edges:
                            if inp_node.in_edge not in completed_edges:
                                dep_ready = False
                                break
                    if dep_ready:
                        ready_edges.append(edge)

                if not ready_edges and not running_futures:
                    sys.stderr.write("ninja: error: could not determine root nodes of build graph\n")
                    return 1

                for edge in ready_edges:
                    if len(running_futures) >= max_jobs:
                        break
                    plan.remove(edge)
                    started_jobs += 1
                    future = executor.submit(self.run_edge, edge, started_jobs, total_jobs, status_fmt, start_time)
                    running_futures[future] = edge

                if not running_futures:
                    break

                done_futures = [fut for fut in list(running_futures.keys()) if fut.done()]
                if not done_futures:
                    time.sleep(0.005)
                    continue

                for fut in done_futures:
                    edge = running_futures.pop(fut)
                    try:
                        retcode, out_str, edge_start_ms, edge_end_ms = fut.result()
                        if retcode == 0:
                            completed_edges.add(edge)
                            finished_jobs += 1
                            if not self.options['quiet']:
                                status_line = format_status(status_fmt, finished_jobs, total_jobs, started_jobs, len(running_futures), start_time)
                                desc = edge.get_description()
                                cmd = edge.get_command()
                                if self.options['v'] or not desc:
                                    print(f"{status_line}{cmd}")
                                else:
                                    print(f"{status_line}{desc}")
                            if out_str.strip():
                                print(out_str.strip())
                        else:
                            failed = True
                            if not self.options['quiet']:
                                status_line = format_status(status_fmt, finished_jobs, total_jobs, started_jobs, len(running_futures), start_time)
                            outs = " ".join(edge.outputs)
                            sys.stderr.write(f"FAILED: [code={retcode}] {outs} \n")
                            cmd = edge.get_command()
                            sys.stderr.write(f"{cmd}\n")
                            if out_str:
                                sys.stderr.write(f"{out_str}")
                            sys.stderr.write("ninja: build stopped: subcommand failed.\n")
                            return 1
                    except Exception as ex:
                        failed = True
                        sys.stderr.write(f"ninja: error: {ex}\n")
                        return 1

        return 0

    def run_edge(self, edge, job_num, total_jobs, status_fmt, start_time):
        edge_start_ms = int(time.time() * 1000)
        cmd = edge.get_command()
        if not cmd or self.options['n']:
            edge_end_ms = int(time.time() * 1000)
            return 0, "", edge_start_ms, edge_end_ms

        rspfile = edge.get_rspfile()
        rspcontent = edge.get_rspfile_content()
        if rspfile:
            if os.path.dirname(rspfile):
                os.makedirs(os.path.dirname(rspfile), exist_ok=True)
            with open(rspfile, 'w', encoding='utf-8') as f:
                f.write(rspcontent)

        proc = subprocess.Popen(cmd, shell=True, executable='/bin/sh', stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        out_bytes, _ = proc.communicate()
        retcode = proc.returncode
        out_str = out_bytes.decode('utf-8', errors='replace') if out_bytes else ""

        edge_end_ms = int(time.time() * 1000)

        if rspfile and 'keeprsp' not in self.options['debug']:
            try:
                os.remove(rspfile)
            except Exception:
                pass

        if retcode == 0:
            depfile = edge.get_depfile()
            deps_type = edge.get_deps()
            if deps_type == 'gcc' and depfile:
                parsed_deps = parse_depfile(depfile)
                if parsed_deps and edge.outputs:
                    out_mtime = int(os.path.getmtime(edge.outputs[0]) * 1e9) if os.path.exists(edge.outputs[0]) else edge_end_ms * 1000000
                    self.deps.record(edge.outputs[0], out_mtime, parsed_deps)
                if 'keepdepfile' not in self.options['debug'] and os.path.exists(depfile):
                    try:
                        os.remove(depfile)
                    except Exception:
                        pass

            if edge.outputs:
                out_mtime = int(os.path.getmtime(edge.outputs[0]) * 1e9) if os.path.exists(edge.outputs[0]) else edge_end_ms * 1000000
                cmd_hash = compute_cmd_hash(cmd)
                self.log.record(edge_start_ms, edge_end_ms, out_mtime, edge.outputs[0], cmd_hash)

        return retcode, out_str, edge_start_ms, edge_end_ms

def format_status(fmt, finished, total, started, running, start_time):
    elapsed = time.time() - start_time
    remaining = total - finished
    pct = int((finished / total) * 100) if total > 0 else 100
    rate = (finished / elapsed) if elapsed > 0 else 0.0

    res = []
    i = 0
    n = len(fmt)
    while i < n:
        if fmt[i] == '%':
            if i + 1 < n:
                ch = fmt[i+1]
                if ch == 's': res.append(str(started))
                elif ch == 'f': res.append(str(finished))
                elif ch == 't': res.append(str(total))
                elif ch == 'r': res.append(str(running))
                elif ch == 'u': res.append(str(remaining))
                elif ch == 'p': res.append(f"{pct:3d}%")
                elif ch == 'o': res.append(f"{rate:.1f}")
                elif ch == 'e': res.append(f"{elapsed:.3f}")
                elif ch == '%': res.append('%')
                else: res.append('%' + ch)
                i += 2
            else:
                res.append('%')
                i += 1
        else:
            res.append(fmt[i])
            i += 1
    return ''.join(res)

def print_help(prog_name):
    default_j = get_default_j()
    help_text = f"""usage: ninja [options] [targets...]

if targets are unspecified, builds the 'default' target (see manual).

options:
  --version      print ninja version ("{VERSION}")
  -v, --verbose  show all command lines while building
  --quiet        don't show progress status, just command output

  -C DIR   change to DIR before doing anything else
  -f FILE  specify input build file [default=build.ninja]

  -j N     run N jobs in parallel (0 means infinity) [default={default_j} on this system]
  -k N     keep going until N jobs fail (0 means infinity) [default=1]
  -l N     do not start new jobs if the load average is greater than N
  -n       dry run (don't run commands but act like they succeeded)

  -d MODE  enable debugging (use '-d list' to list modes)
  -t TOOL  run a subtool (use '-t list' to list subtools)
    terminates toplevel options; further flags are passed to the tool
  -w FLAG  adjust warnings (use '-w list' to list warnings)
"""
    sys.stderr.write(help_text)

def main():
    prog_name = sys.argv[0]

    args = sys.argv[1:]
    build_file = 'build.ninja'
    jobs = get_default_j()
    keep_going = 1
    load_avg = 0.0
